    {
      "text": "Snapshot failures cause writes to be refused when rdb_last_bgsave_status is err (MISCONF).",
      "evidence_ids": ["RB-019#4"],
      "quote": "rdb_last_bgsave_status:err -> MISCONF path"
    },
    {
      "text": "Memory exhaustion causes writes to be refused when used_memory reaches maxmemory with noeviction policy (OOM).",
      "evidence_ids": ["RB-019#1"],
      "quote": "used_memory at maxmemory, noeviction -> OOM path"
    }
  ],
  "next_checks": [
    "Run `redis-cli INFO persistence` and look for `rdb_last_bgsave_status:err`.",
    "Run `redis-cli INFO memory` and compare `used_memory_human` to `maxmemory_human` and check `maxmemory_policy`.",
    "Check recent Redis logs for messages like \"fork: Cannot allocate memory\" or \"MISCONF\"."
  ]
